import { z } from "zod";
const safeText=(max:number)=>z.string().trim().min(1).max(max);
const safeUrl=z.string().url().refine((value)=>["https:","http:"].includes(new URL(value).protocol),"Only HTTP(S) URLs are allowed");
export const qChatChoiceOptionSchema=z.object({value:safeText(64),label:safeText(64),color:z.string().regex(/^#[0-9a-fA-F]{6}$/).optional(),disabled:z.boolean().optional()}).strict();
const actionSchema=z.object({label:safeText(48),name:z.enum(["product.select","product.add","product.open"]),payload:z.record(z.union([z.string().max(256),z.number().finite(),z.boolean()]))}).strict();
export const qChatProductCardSchema=z.object({type:z.literal("product-card"),id:safeText(80),title:safeText(100),description:safeText(280).optional(),image:z.object({src:safeUrl,alt:safeText(140)}).strict().optional(),price:z.object({amount:z.number().finite().nonnegative(),currency:z.string().length(3).transform((v)=>v.toUpperCase())}).strict(),tags:z.array(safeText(32)).max(6).optional(),colors:z.array(qChatChoiceOptionSchema).max(12).optional(),sizes:z.array(qChatChoiceOptionSchema).max(12).optional(),primaryAction:actionSchema.optional(),secondaryAction:actionSchema.optional()}).strict();
export const qChatProductCollectionSchema=z.object({type:z.literal("product-collection"),id:safeText(80),direction:z.enum(["horizontal","vertical"]),title:safeText(100).optional(),items:z.array(qChatProductCardSchema).min(1).max(12)}).strict();
export const qChatStatusSchema=z.object({type:z.literal("status"),id:safeText(80),variant:z.enum(["empty","unavailable","error"]),title:safeText(100),description:safeText(280).optional()}).strict();
export const qChatInfoCardSchema=z.object({type:z.literal("info-card"),id:safeText(80),title:safeText(100),description:safeText(500),facts:z.array(z.object({label:safeText(64),value:safeText(120)}).strict()).max(8).optional(),source:safeText(120).optional()}).strict();
export const qChatUIDocumentSchema=z.object({version:z.literal("1"),id:safeText(80),layout:z.enum(["container","scroll"]),children:z.array(z.discriminatedUnion("type",[qChatProductCollectionSchema,qChatProductCardSchema,qChatStatusSchema,qChatInfoCardSchema])).min(1).max(16)}).strict();
export type QChatUIDocumentInput=z.input<typeof qChatUIDocumentSchema>;
